// Of Me 0.2: local-first handmade interface.
const clock=d=>new Date(d).toLocaleString(undefined,{dateStyle:'medium',timeStyle:'short'});
const active=()=>items.filter(i=>!i.deletedAt);
const baseBind=bind,baseSave=save,baseDetail=detail,baseSettings=settingsPage,baseCommit=commit,baseSetFilter=setFilter,baseReload=reload,baseTheme=applyTheme;
let showAll=false, page=0, selectMode=false, picked=new Set(), sortMode='custom', gridMode=false, portraitSelected=null, portraitEditing=true, drag=null;
const safeImg=s=>typeof s==='string'&&/^data:image\/(png|jpeg|webp|gif);base64,/i.test(s)?s:'';
const palette=['#e3e7d6','#e8c7cf','#c8d8ea','#d9cde8','#eed6b9','#f2e2a9'];
const labels={home:'Home',library:'Threads',save:'Keep',mirror:'Mirror',settings:'Settings'};
const glyphs=['✿','♡','✧','♫','❧','✳'];
const svgFlower=()=>{const pts=[];for(const [cx,cy] of [[36,40],[84,40],[60,77]]){for(let k=0;k<5;k++){const a=k*2*Math.PI/5;for(let j=0;j<7;j++){const t=j*2*Math.PI/7;pts.push([cx+Math.cos(a)*11+Math.cos(t)*6,cy+Math.sin(a)*11+Math.sin(t)*6])}}pts.push([cx,cy])}for(let j=0;j<16;j++){pts.push([60+Math.sin(j*.5)*9,85+j*3])}return `<svg viewBox="0 0 120 140" aria-hidden="true">${pts.map(([x,y])=>`<circle cx="${x}" cy="${y}" r="1.7" fill="#8d976d"/>`).join('')}</svg>`};
const mirrorArt='<svg viewBox="0 0 100 80" aria-hidden="true"><ellipse cx="50" cy="33" rx="24" ry="29" fill="#e5c4c7" stroke="#9d6872" stroke-width="3"/><ellipse cx="50" cy="33" rx="19" ry="24" fill="#f8eee2" stroke="#b98a91" stroke-dasharray="2 3"/><path d="M48 62 Q40 73 48 78 Q56 80 54 63" fill="#b98a91"/><path d="M41 21 L45 14 M47 23 L54 12" stroke="#c6b6af" stroke-width="2"/></svg>';
applyTheme=function(){baseTheme();document.documentElement.style.setProperty('--bg',/^#[0-9a-f]{6}$/i.test(settings.background||'')?settings.background:'#f7f2e8');document.documentElement.style.setProperty('--feather',Math.max(0,Math.min(1.4,Number(settings.feather??.45)))+'px');document.body.classList.toggle('no-texture',settings.texture===false);if(settings.onlineFonts&&!document.getElementById('ofmeFonts')){const l=document.createElement('link');l.id='ofmeFonts';l.rel='stylesheet';l.href='https://fonts.googleapis.com/css2?family=Cormorant+Garamond:ital,wght@0,400;0,600;1,400&family=Inter:wght@400;500;600&display=swap';document.head.append(l)}else if(!settings.onlineFonts)document.getElementById('ofmeFonts')?.remove()};
nav=function(){ $('#nav').innerHTML=Object.keys(labels).map(x=>`<button data-tab="${x}" class="${tab===x?'active':''}" aria-label="${labels[x]}">${safeImg(settings.navIcons?.[x])?`<img class="nav-photo" src="${settings.navIcons[x]}" alt="">`:icon(x)}${labels[x]}</button>`).join('');$('#nav').querySelectorAll('button').forEach(b=>b.onclick=()=>go(b.dataset.tab))};
home=function(){return `<section class="hero"><div class="eyebrow">a little of who I am</div><div class="home-art">${safeImg(settings.homePhoto)?`<img class="home-photo" src="${settings.homePhoto}" alt="My home collage">`:`<svg viewBox="0 0 300 124" aria-hidden="true"><defs><pattern id="dots" width="6" height="6" patternUnits="userSpaceOnUse"><circle cx="3" cy="3" r="1.2" fill="#8d976d"/></pattern></defs><path d="M20 110 Q15 20 80 16 Q117 9 107 40 Q95 64 72 40 Q55 19 34 61 M280 110 Q285 20 220 16 Q183 9 193 40 Q205 64 228 40 Q245 19 266 61" fill="none" stroke="#8d976d" stroke-width="3" stroke-dasharray=".5 5" stroke-linecap="round"/><path d="M75 100 C33 40 112 25 150 86 C188 25 267 40 225 100 L150 120Z" fill="#e8c7cf" opacity=".7"/><path d="M89 88 Q150 22 211 88" fill="none" stroke="#b85d63" stroke-width="1.6" stroke-dasharray="2 5"/><text x="150" y="80" text-anchor="middle" font-family="Georgia" font-size="38" fill="#a76069">♡</text></svg>`}</div><h1>of me.</h1><p class="paper-note welcome">${esc(settings.welcome??'Here I am, in all my little pieces.')}</p></section><div class="stitch">♡</div><div class="home-grid"><button class="home-tile" data-go="library"><span class="tile-art">${svgFlower()}</span><strong>My threads</strong></button><button class="home-tile" data-go="mirror"><span class="tile-art">${mirrorArt}</span><strong>The mirror</strong></button></div><section class="section panel stack"><h2>A little piece of me</h2><p class="muted">Something from my own archive, waiting to be remembered.</p><button class="btn" id="rediscover" ${active().length?'':'disabled'}>Rediscover a keepsake</button></section><p class="home-end">Nothing to catch up on. Just a place to be.</p>`};
function threadCard(c,k){const n=active().filter(i=>i.collections?.includes(c.id)).length;return `<button class="collection" data-collection="${esc(c.id)}"><span class="coverart" style="background:${/^#[0-9a-f]{6}$/i.test(c.color||'')?c.color:palette[k%palette.length]}">${safeImg(c.cover||c.icon)?`<img class="${safeImg(c.cover)?'thread-cover-art':'thread-icon-art'}" src="${safeImg(c.cover||c.icon)}" alt="">`:glyphs[k%glyphs.length]}</span><strong>${safeImg(c.icon)?`<img class="nav-photo" style="width:20px;height:20px;vertical-align:middle;margin-right:4px" src="${c.icon}" alt="">`:""}${esc(c.name)}</strong><span class="muted">${n} keepsake${n===1?'':'s'}</span></button>`}
function ytId(s){try{const u=new URL(s);let v=u.hostname==='youtu.be'?u.pathname.slice(1).split('/')[0]:/(^|\.)youtube\.com$/.test(u.hostname)?u.searchParams.get('v')||u.pathname.match(/^\/(?:shorts|embed|live)\/([^/]+)/)?.[1]:'';return /^[\w-]{11}$/.test(v||'')?v:''}catch{return ''}}
function thumb(i){return i.media?.type?.startsWith('image/')?`<img src="${objectURL(i.media)}" alt="">`:safeImg(i.thumbnail)?`<img src="${i.thumbnail}" alt="">`:icons[i.type]||'◇'}
function itemCard(i){return `<button class="item" data-open="${esc(i.id)}"><span class="thumb">${thumb(i)}</span><span><strong>${esc(i.title)}</strong><small>${esc(i.type)} · ${esc(clock(i.created))}</small><small>${i.media?'Stored offline':i.url?'Link only':''}</small></span><span class="arrow">›</span></button>`}
function filtered(){const c=filter.collection;let a=active().filter(i=>(!c||(c==='inbox'?!i.collections?.length:i.collections?.includes(c)))&&(!filter.q||[i.title,i.url,i.type,i.reason,i.meaning,i.application,i.notes,...(i.tags||[]),...(i.feelings||[]),...(i.collections||[]).map(collectionName)].join(' ').toLowerCase().includes(filter.q.toLowerCase()))&&(!filter.tag||i.tags?.includes(filter.tag))&&(!filter.type||i.type===filter.type)&&(!filter.feeling||i.feelings?.includes(filter.feeling)));const order=settings.collections.find(x=>x.id===c)?.order||[];if(sortMode==='custom'&&c&&c!=='inbox'){const pos=x=>{const n=order.indexOf(x.id);return n<0?1e9:n};a.sort((x,y)=>pos(x)-pos(y)||y.created-x.created)}else if(sortMode==='oldest')a.sort((x,y)=>x.created-y.created);else if(sortMode==='title')a.sort((x,y)=>x.title.localeCompare(y.title));else if(sortMode==='type')a.sort((x,y)=>x.type.localeCompare(y.type)||y.created-x.created);else a.sort((x,y)=>y.created-x.created);return a}
function pageList(a){const size=12;page=Math.max(0,Math.min(page,Math.ceil(a.length/size)-1));const part=a.slice(page*size,(page+1)*size);return `${part.length?`<div class="stack ${gridMode&&!selectMode?'griditems':''}">${part.map((i,k)=>selectMode?`<div class="selectline"><input type="checkbox" aria-label="Select ${esc(i.title)}" data-pick="${esc(i.id)}" ${picked.has(i.id)?'checked':''}>${itemCard(i)}${filter.collection&&filter.collection!=='inbox'&&sortMode==='custom'&&!filter.q&&!filter.tag&&!filter.type&&!filter.feeling?`<div class="orderbtns"><button data-order="${esc(i.id)}" data-dir="-1" aria-label="Move up" ${page*size+k===0?'disabled':''}>↑</button><button data-order="${esc(i.id)}" data-dir="1" aria-label="Move down" ${page*size+k===a.length-1?'disabled':''}>↓</button></div>`:''}</div>`:itemCard(i)).join('')}</div>`:'<div class="empty">Nothing here yet. Keep what resonates.</div>'}${a.length>size?`<div class="pagebar"><button class="btn" id="prevPage" ${page===0?'disabled':''}>Previous</button><span class="muted">${page+1} / ${Math.ceil(a.length/size)}</span><button class="btn" id="nextPage" ${(page+1)*size>=a.length?'disabled':''}>Next</button></div>`:''}`}
library=function(){const c=settings.collections.find(x=>x.id===filter.collection),a=filtered();const browsing=!!(filter.collection||filter.q||filter.tag||filter.type||filter.feeling||showAll);return `<div class="sectionhead"><h1>${c?esc(c.name):filter.collection==='inbox'?'Unthreaded':browsing?'All of me':'My threads'}</h1><button class="ghost" id="newCollection">+ Thread</button></div>${browsing?`<button class="ghost" id="threadsBack">‹ All threads</button>${c?`<div class="threadhead">${safeImg(c.cover)?`<img src="${c.cover}" alt="">`:''}<p>${esc(c.description||'')}</p><button class="ghost" id="editCollection">Edit thread</button></div>`:''}`:`<p class="paper-note" style="text-align:left">Different strands of the same person.</p><div class="section grid">${settings.collections.map(threadCard).join('')}<button class="collection" id="allItems"><span class="coverart" style="background:#e9ddca">✧</span><strong>All of me</strong><span class="muted">${active().length} keepsakes</span></button><button class="collection" data-collection="inbox"><span class="coverart" style="background:#e7dfed">❧</span><strong>Unthreaded</strong><span class="muted">${active().filter(i=>!i.collections?.length).length} keepsakes</span></button></div>`}<section class="section stack"><input id="search" type="search" placeholder="Find a keepsake" value="${esc(filter.q)}">${browsing?`<div class="filter"><select id="ftag" aria-label="Tag"><option value="">All tags</option>${settings.tags.map(t=>`<option ${filter.tag===t?'selected':''}>${esc(t)}</option>`).join('')}</select><select id="ftype" aria-label="Media"><option value="">All media</option>${types.map(t=>`<option ${filter.type===t?'selected':''}>${t}</option>`).join('')}</select><select id="ffeeling" aria-label="Feeling"><option value="">All feelings</option>${uniq(active().flatMap(i=>i.feelings||[])).sort().map(t=>`<option ${filter.feeling===t?'selected':''}>${esc(t)}</option>`).join('')}</select><select id="sortMode" aria-label="Sort"><option value="custom" ${sortMode==='custom'?'selected':''}>${c?'Custom order':'Default order'}</option>${[['newest','Newest'],['oldest','Oldest'],['title','Title'],['type','Media type']].map(([v,t])=>`<option value="${v}" ${sortMode===v?'selected':''}>${t}</option>`).join('')}</select></div><div class="row between"><span class="muted">${a.length} keepsakes</span><div class="row"><button class="ghost" id="gridToggle">${gridMode?'List':'Grid'}</button><button class="ghost" id="selectMode">${selectMode?'Done':'Select'}</button></div></div>${selectMode?`<div class="actions stack"><div class="row between"><span>${picked.size} selected</span><button class="ghost" id="selectAll">Select all matching</button></div><div class="row">${[['move','Move'],['add','Add to threads'],['duplicate','Duplicate'],['remove','Remove'],['delete','Delete']].map(([k,l])=>`<button class="${k==='delete'?'danger':'btn'}" data-batch="${k}" ${!picked.size||k==='remove'&&!c?'disabled':''}>${l}</button>`).join('')}</div></div>`:''}<div id="results">${pageList(a)}</div>`:''}</section>`};
setFilter=function(k,v){page=0;selectMode=false;picked.clear();sortMode='custom';showAll=false;baseSetFilter(k,v)};
async function resizeImage(f,max=900,format='image/jpeg'){if(!f)return '';const u=URL.createObjectURL(f);try{const img=new Image();img.src=u;await img.decode();const ratio=Math.min(1,max/Math.max(img.width,img.height));const c=document.createElement('canvas');c.width=Math.max(1,Math.round(img.width*ratio));c.height=Math.max(1,Math.round(img.height*ratio));const ctx=c.getContext('2d');ctx.imageSmoothingEnabled=true;ctx.imageSmoothingQuality='high';ctx.drawImage(img,0,0,c.width,c.height);return c.toDataURL(format,.92)}finally{URL.revokeObjectURL(u)}}
collectionModal=function(c){modal(`<div class="stack"><h2>${c?'Edit thread':'Create a thread'}</h2><label>Name</label><input id="collectionInput" value="${esc(c?.name||'')}" placeholder="A name for this strand"><label>Description (optional)</label><textarea id="threadDescription">${esc(c?.description||'')}</textarea><label>Colour</label><input id="threadColor" type="color" value="${/^#[0-9a-f]{6}$/i.test(c?.color||'')?c.color:'#e3e7d6'}"><label>Cover photo</label><input id="threadCover" type="file" accept="image/*"><label><input id="clearCover" type="checkbox"> Remove existing cover</label><label>Icon photo</label><input id="threadIcon" type="file" accept="image/*"><label><input id="clearIcon" type="checkbox"> Remove existing icon</label><button class="btn primary" id="saveCollection">${c?'Save changes':'Create thread'}</button>${c?'<button class="danger" id="removeCollection">Delete thread (keep keepsakes)</button>':''}</div>`);on('#saveCollection',async()=>{try{const name=$('#collectionInput').value.trim();if(!name)return toast('Give your thread a name.');if(settings.collections.some(x=>norm(x.name)===norm(name)&&x.id!==c?.id))return toast('A thread already has that name.');const x={...c,id:c?.id||id(),name,description:$('#threadDescription').value,color:$('#threadColor').value,cover:$('#clearCover').checked?'':c?.cover||'',icon:$('#clearIcon').checked?'':c?.icon||''};const f=$('#threadCover').files[0],g=$('#threadIcon').files[0];if(f)x.cover=await resizeImage(f);if(g)x.icon=await resizeImage(g,512,'image/png');settings.collections=c?settings.collections.map(y=>y.id===c.id?x:y):[...settings.collections,x];if(!c&&tab==='save')draft.collections.push(x.id);await storeSettings();closeModal();render()}catch(e){error(e)}});on('#removeCollection',async()=>{if(!confirm('Delete this thread? Its keepsakes will stay in your archive.'))return;try{settings.collections=settings.collections.filter(x=>x.id!==c.id);await tx(['items','settings'],'readwrite',t=>{const s=t.objectStore('items');items.filter(i=>i.collections?.includes(c.id)).forEach(i=>s.put({...i,collections:i.collections.filter(x=>x!==c.id),updated:Date.now()}));t.objectStore('settings').put(settings,'main')});await reload();closeModal();setFilter('collection','')}catch(e){error(e)}})};
async function batch(kind,dest=[]){const chosen=active().filter(i=>picked.has(i.id));if(!chosen.length)return;try{await tx(['items'],'readwrite',t=>{const s=t.objectStore('items');for(const i of chosen){const now=Date.now();if(kind==='duplicate'){s.put({...i,id:id(),created:i.created,duplicatedAt:now,updated:now,collections:dest});continue}let c=i.collections||[];if(kind==='move')c=uniq([...c.filter(x=>x!==filter.collection),...dest]);if(kind==='add')c=uniq([...c,...dest]);if(kind==='remove')c=c.filter(x=>x!==filter.collection);s.put({...i,collections:c,updated:now,...(kind==='delete'?{deletedAt:now}:{})})}});await reload();picked.clear();selectMode=false;closeModal();render();toast('Changes saved.')}catch(e){error(e)}}
function batchDialog(kind){if(kind==='delete'||kind==='remove'){if(confirm(kind==='delete'?'Move selected keepsakes to Recently Deleted in all threads?':'Remove selected keepsakes from this thread only?'))batch(kind);return}if(!settings.collections.length)return toast('Create a destination thread first.');modal(`<div class="stack"><h2>${{move:'Move to threads',add:'Add to threads',duplicate:'Duplicate to threads'}[kind]}</h2><p class="muted">${kind==='duplicate'?'Separate reflections; original upload time is retained.':kind==='move'?'Remove from the current thread and add to the selected destinations. Other memberships remain.':'The same keepsake will belong to all selected threads.'}</p><div class="checklist">${settings.collections.filter(c=>kind!=='move'||c.id!==filter.collection).map(c=>`<label><input type="checkbox" data-dest="${esc(c.id)}">${esc(c.name)}</label>`).join('')}</div><button class="btn primary" id="batchCommit">Confirm</button></div>`);on('#batchCommit',()=>{const a=[...document.querySelectorAll('[data-dest]:checked')].map(x=>x.dataset.dest);if(!a.length)return toast('Choose at least one thread.');batch(kind,a)})}
async function fetchMetadata(target,quiet=false){const u=safeURL(target.url);if(!u)return;const y=ytId(u);let endpoint='';try{const h=new URL(u).hostname;if(y)endpoint='https://www.youtube.com/oembed?format=json&url='+encodeURIComponent(u);else if(/(^|\.)tiktok\.com$/.test(h))endpoint='https://www.tiktok.com/oembed?url='+encodeURIComponent(u);else if(h==='open.spotify.com')endpoint='https://open.spotify.com/oembed?url='+encodeURIComponent(u);else if(h==='soundcloud.com')endpoint='https://soundcloud.com/oembed?format=json&url='+encodeURIComponent(u);if(!endpoint){if(!quiet)toast('This source needs a manual title or screenshot.');return}const abort=new AbortController();const timer=setTimeout(()=>abort.abort(),6500);let data;try{const r=await fetch(endpoint,{signal:abort.signal,credentials:'omit',referrerPolicy:'no-referrer'});if(!r.ok)throw Error('Metadata unavailable');data=await r.json()}finally{clearTimeout(timer)}if(typeof data.title==='string'&&(!target.title||target.title===`${detect(u)} save`||target.autoTitle)){target.title=data.title.slice(0,500);target.autoTitle=true}target.creator=typeof data.author_name==='string'?data.author_name.slice(0,300):'';target.remoteThumb=safeURL(data.thumbnail_url);if(draft===target&&tab==='save'){if($('#title'))$('#title').value=target.title;if($('#metadataStatus'))$('#metadataStatus').textContent=target.creator?'Found · '+target.creator:'Title found';}if(!quiet)toast('Media information retrieved.')}catch(e){if(!quiet)toast('Automatic title unavailable. You can still name it yourself.');}}
save=function(){return baseSave().replace(/Edit moment/g,'Edit keepsake').replace(/Keep a moment/g,'Something to keep.').replace('Save now. Understand it whenever you\'re ready.','Keep what resonates. Reflections are always optional.').replace('Give it a name','Title').replace('<button class="ghost" id="paste">Paste from clipboard</button>','<div class="row"><button class="ghost" id="paste">Paste from clipboard</button><button class="ghost" id="fetchMeta">Find title & preview</button></div><p class="help" id="metadataStatus">Titles are retrieved when the source permits it.</p>').replace('<div><label for="media">','<div id="previewUpload"><label for="thumbFile">Custom preview photo (optional)</label><input id="thumbFile" type="file" accept="image/*">'+(safeImg(draft.thumbnail)?`<img class="preview" src="${draft.thumbnail}" alt="Preview"><button class="ghost" id="clearThumb">Remove preview</button>`:'')+'</div><div><label for="media">').replace(/Collections/g,'Threads').replace(/collection\./g,'thread.').replace('use Inbox','keep it Unthreaded').replace('Keep this moment','Keep this ♡').replace('What makes it part of me?','What about this is of me?').replace('Something I want to remember, practice or become…','If anywhere…').replace('Save now, reflect later','Keep this ♡')};
commit=async function(){if(!draft)return;const target=draft;const original=items.find(i=>i.id===target.id);if(original&&['reason','meaning','application','notes','feelings'].some(k=>JSON.stringify(original[k])!==JSON.stringify(target[k]))&&['reason','meaning','application','notes','feelings'].some(k=>original[k]?.length)){const text=[['reason','Why I saved it'],['meaning','What it meant'],['application','Where it applied'],['notes','Notes']].filter(([k])=>original[k]).map(([k,t])=>t+': '+original[k]).concat(original.feelings?.length?['Feelings: '+original.feelings.join(', ')]:[]).join('\n\n');if(!target.reflections?.some(r=>r.date===original.updated&&r.text===text))target.reflections=[...(target.reflections||[]),{date:original.updated,text}]}if(target.url&&settings.autoMetadata!==false&&target.metadataSource!==safeURL(target.url)){await fetchMetadata(target,true);if(draft!==target)return}return baseCommit()};
detail=function(){let h=baseDetail(),i=items.find(x=>x.id===selectedId);if(!i)return h;h=h.replace(fmt(i.created),esc(clock(i.created))).replace(/Edit moment/g,'Edit keepsake').replace(/Delete moment/g,'Delete keepsake').replace('Still waiting to be reflected on. Whenever you feel ready.','Some things are simply worth keeping.').replace('Offline copy','Stored offline · independent copy').replace('class="panel">'+(i.media?.type?.startsWith('video/')?'<video':'<never'),'class="mediaframe"><video');const preview=!i.media&&(safeImg(i.thumbnail)||i.remoteThumb||ytId(i.url))?`<div class="mediaframe stack">${safeImg(i.thumbnail)?`<img class="preview" src="${i.thumbnail}" alt="Saved preview">`:`<button class="btn" id="loadPreview">Load source preview</button><div id="remotePreview"></div>`}<p class="muted">${esc(i.creator||'Link only · not stored offline')}</p></div>`:'';const canEmbed=!!ytId(i.url);const extra=(i.url&&!i.media?'<button class="ghost" id="refreshSavedMeta">Find title & preview</button>':'')+preview+(canEmbed&&!i.media?'<div class="panel stack"><button class="btn" id="playEmbed">Play YouTube here (online)</button><p class="help">YouTube may show related content when playback ends.</p><div id="embedArea"></div></div>':'')+(i.duplicatedAt?`<p class="muted">Duplicate created ${esc(clock(i.duplicatedAt))}</p>`:'');return h.replace('</h1>','</h1>'+extra).replace('<div class="panel stack"><h2>My reflection','<div class="stitch">♡</div><div class="panel stack"><h2>My reflection')};
rank=function(key){const counts=new Map();active().forEach(i=>uniq(i[key]||[]).forEach(t=>counts.set(t,(counts.get(t)||0)+1)));return [...counts.entries()].sort((a,b)=>b[1]-a[1]||a[0].localeCompare(b[0]))};
function portrait(){settings.portrait ||= {background:'#e8c7cf',layers:[],snapshots:[]};return settings.portrait}
function layerHtml(l){const x=Math.max(-50,Math.min(150,Number.isFinite(+l.x)?+l.x:50)),y=Math.max(-50,Math.min(150,Number.isFinite(+l.y)?+l.y:50)),w=Math.max(10,Math.min(100,+l.w||40)),r=Math.max(-180,Math.min(180,+l.r||0));return `<div class="portrait-layer ${l.id===portraitSelected&&portraitEditing?'selected-layer':''} ${l.kind==='text'?'text-layer':''}" data-layer="${esc(l.id)}" style="left:${x}%;top:${y}%;width:${w}%;--rot:${r}deg;${l.kind==='text'?`font-size:${Math.max(12,Math.min(70,+l.size||26))}px;color:${/^#[0-9a-f]{6}$/i.test(l.color||'')?l.color:'#382c28'}`:''}">${l.kind==='image'&&safeImg(l.src)?`<img src="${l.src}" alt="">`:esc(l.text||'')}</div>`}
function portraitPanel(){const p=portrait(),l=p.layers.find(x=>x.id===portraitSelected);return `<section class="section panel stack"><div class="sectionhead"><h2>Living self-portrait</h2><button class="ghost" id="portraitEdit">${portraitEditing?'Done':'Edit'}</button></div><p class="paper-note" style="text-align:left">A portrait perpetually in the making.</p><div id="portraitCanvas" class="canvas-wrap" style="background:${/^#[0-9a-f]{6}$/i.test(p.background)?p.background:'#e8c7cf'}">${p.layers.map(layerHtml).join('')}${p.layers.length?'':'<span style="position:absolute;inset:40% 10%;text-align:center;color:#71535a;font:italic 24px Georgia">Fragments of me ♡</span>'}</div>${portraitEditing?`<div class="row"><label for="portraitPhoto" class="btn">+ Photo</label><input id="portraitPhoto" class="hidden" type="file" accept="image/*" multiple><button class="btn" id="portraitText">+ Words</button><button class="btn" id="portraitKeep">+ Keepsake</button><button class="btn" id="portraitMotif">+ Motif</button></div><div class="row"><label for="portraitBg">Canvas colour</label><input id="portraitBg" type="color" value="${p.background}"></div>${l?`<div class="portrait-controls stack"><p class="muted">Drag the selected piece to move it.</p><label>Width <input id="layerWidth" type="range" min="10" max="100" value="${l.w||40}"></label><label>Rotation <input id="layerRotate" type="range" min="-180" max="180" value="${l.r||0}"></label>${l.kind==='text'?`<label>Text size <input id="layerSize" type="range" min="12" max="70" value="${l.size||26}"></label><label>Ink <input id="layerColor" type="color" value="${l.color||'#382c28'}"></label><button class="btn" id="editLayerText">Edit words</button>`:''}<div class="row"><button class="btn" id="layerFront">Bring forward</button><button class="btn" id="layerBack">Send back</button><button class="danger" id="layerRemove">Remove</button></div></div>`:''}`:''}<div class="row"><button class="btn" id="portraitSnapshot" ${p.layers.length?'':'disabled'}>Keep dated snapshot</button><button class="btn" id="portraitExport" ${p.layers.length?'':'disabled'}>Export image</button></div>${p.snapshots.length?`<details><summary>Past portraits (${p.snapshots.length})</summary><div class="stack">${p.snapshots.map((s,k)=>`<button class="item" data-snapshot="${k}"><span class="thumb"><img src="${safeImg(s.image)}" alt=""></span><strong>${esc(clock(s.date))}</strong><span>›</span></button>`).join('')}</div></details>`:''}</section>`}
mirror=function(){const tags=rank('tags'),feel=rank('feelings');return `<h1>The mirror</h1><p class="paper-note" style="text-align:left">The things I see in the things I keep.</p>${portraitPanel()}<section class="section panel stack"><h2>Common threads</h2>${tags.length?tags.map(([t,n])=>{const rel=uniq(active().filter(i=>i.tags?.includes(t)).flatMap(i=>i.collections||[])).map(collectionName).filter(Boolean);return `<button class="btn" data-filtertag="${esc(t)}" style="text-align:left">#${esc(t)} <span class="muted">· ${n} keepsakes</span><div class="help">${esc(rel.join(' · '))}</div></button>`}).join(''):'<p class="muted">Shared tags will reveal connections between your keepsakes.</p>'}</section><section class="section panel stack"><h2>Feelings I've encountered</h2><div class="chips">${feel.length?feel.map(([t,n])=>`<button class="pill" data-filterfeeling="${esc(t)}">${esc(t)} · ${n}</button>`).join(''):'<p class="muted">Your emotional vocabulary gathers here.</p>'}</div><details><summary>Words to explore</summary><p>Tenderness: gentle affection. Yearning: sustained longing. Reverence: profound respect. Bittersweetness: pleasure mingled with sadness. Nostalgia: affectionate longing for the past. Awe: wonder at something extraordinary.</p></details></section><section class="section panel stack"><h2>Things I've discovered about myself</h2>${(settings.discoveries||[]).map((d,k)=>`<div><span class="eyebrow">${esc(clock(d.date))}</span><p style="white-space:pre-wrap">${esc(d.text)}</p><button class="ghost" data-remove-discovery="${k}">Remove</button></div>`).join('')}<textarea id="discoveryText" placeholder="A little something I've noticed…"></textarea><button class="btn" id="saveDiscovery">Keep this thought</button></section><section class="section panel stack"><h2>Then & now</h2>${active().filter(i=>i.reflections?.length).slice(0,12).map(i=>`<button class="btn" data-open="${esc(i.id)}">${esc(i.title)} · ${i.reflections.length} later reflections</button>`).join('')||'<p class="muted">Return to your own words whenever you like.</p>'}</section>`};
async function updatePortrait(renderNow=true){await storeSettings();if(renderNow)render()}
async function addLayer(l){const p=portrait();const x={id:id(),x:50,y:50,w:45,r:0,...l};p.layers.push(x);portraitSelected=x.id;portraitEditing=true;await updatePortrait()}
async function portraitImage(){const p=portrait(),el=$('#portraitCanvas');const c=document.createElement('canvas');c.width=900;c.height=1200;const ctx=c.getContext('2d');ctx.fillStyle=p.background;ctx.fillRect(0,0,c.width,c.height);for(const l of p.layers){ctx.save();ctx.translate(l.x/100*c.width,l.y/100*c.height);ctx.rotate((l.r||0)*Math.PI/180);const w=l.w/100*c.width;if(l.kind==='image'&&safeImg(l.src)){const im=new Image();im.src=l.src;await im.decode();const h=w*im.height/im.width;ctx.drawImage(im,-w/2,-h/2,w,h)}else{const size=(l.size||26)*c.width/(el?.clientWidth||350);ctx.font=`italic ${size}px Georgia`;ctx.fillStyle=l.color||'#382c28';ctx.textAlign='center';ctx.textBaseline='middle';let lines=[];for(const part of String(l.text||'').split('\n')){let line='';for(const word of part.split(' ')){if(line&&ctx.measureText(line+' '+word).width>w){lines.push(line);line=word}else line+=(line?' ':'')+word}lines.push(line)}lines.forEach((line,k)=>ctx.fillText(line,0,(k-(lines.length-1)/2)*size*1.2,w))}ctx.restore()}return c.toDataURL('image/jpeg',.92)}
function downloadData(data,name){const a=document.createElement('a');a.href=data;a.download=name;a.click()}
function bindPortrait(){const p=portrait(),l=p.layers.find(x=>x.id===portraitSelected);on('#portraitEdit',()=>{portraitEditing=!portraitEditing;render()});on('#portraitPhoto',async e=>{try{for(const f of e.target.files)await addLayer({kind:'image',src:await resizeImage(f,1100)})}catch(e){error(e)}},'change');on('#portraitText',()=>{const text=prompt('Words for your portrait');if(text?.trim())addLayer({kind:'text',text:text.trim(),size:26,color:'#382c28'})});on('#portraitMotif',()=>{modal(`<h2>Little ornaments</h2><div class="row">${['♡','✿','♫','✧','❧','✳','☾','∞'].map(t=>`<button class="btn" data-motif="${t}">${t}</button>`).join('')}</div>`);document.querySelectorAll('[data-motif]').forEach(b=>b.onclick=()=>{closeModal();addLayer({kind:'text',text:b.dataset.motif,size:48,color:'#a46070',w:25})})});on('#portraitKeep',()=>{modal(`<h2>A piece from my archive</h2><div class="stack">${active().map(i=>`<button class="btn" data-portrait-keep="${esc(i.id)}">${esc(i.title)}</button>`).join('')||'<p>Nothing kept yet.</p>'}</div>`);document.querySelectorAll('[data-portrait-keep]').forEach(b=>b.onclick=async()=>{try{const i=active().find(x=>x.id===b.dataset.portraitKeep);closeModal();if(i.media?.type?.startsWith('image/'))await addLayer({kind:'image',src:await resizeImage(i.media,1100),keepId:i.id});else if(safeImg(i.thumbnail))await addLayer({kind:'image',src:i.thumbnail,keepId:i.id});else await addLayer({kind:'text',text:(i.type==='Song'?'♫ ':'')+i.title,size:24,color:'#382c28',keepId:i.id})}catch(e){error(e)}})});on('#portraitBg',async e=>{p.background=e.target.value;await updatePortrait()},'change');if(l){for(const [sel,key] of [['#layerWidth','w'],['#layerRotate','r'],['#layerSize','size'],['#layerColor','color']])on(sel,async e=>{l[key]=key==='color'?e.target.value:+e.target.value;await updatePortrait()},'change');on('#editLayerText',()=>{const v=prompt('Words',l.text);if(v!==null){l.text=v;updatePortrait()}});on('#layerFront',()=>{p.layers=p.layers.filter(x=>x!==l).concat(l);updatePortrait()});on('#layerBack',()=>{p.layers=[l,...p.layers.filter(x=>x!==l)];updatePortrait()});on('#layerRemove',()=>{p.layers=p.layers.filter(x=>x!==l);portraitSelected=null;updatePortrait()})}document.querySelectorAll('[data-layer]').forEach(el=>{el.onpointerdown=e=>{const v=p.layers.find(x=>x.id===el.dataset.layer);if(!portraitEditing){if(v.keepId&&active().some(i=>i.id===v.keepId))openItem(v.keepId);return}e.preventDefault();const bounds=$('#portraitCanvas').getBoundingClientRect();portraitSelected=v.id;drag={v,el,bounds,startX:e.clientX,startY:e.clientY,x:v.x,y:v.y};el.setPointerCapture(e.pointerId)};el.onpointermove=e=>{if(!drag||drag.el!==el)return;const {v,bounds,startX,startY,x,y}=drag;v.x=Math.max(0,Math.min(100,x+(e.clientX-startX)/bounds.width*100));v.y=Math.max(0,Math.min(100,y+(e.clientY-startY)/bounds.height*100));el.style.left=v.x+'%';el.style.top=v.y+'%'};el.onpointerup=el.onpointercancel=()=>{if(drag?.el===el){drag=null;updatePortrait()}}});on('#portraitSnapshot',async()=>{try{p.snapshots.unshift({date:Date.now(),image:await portraitImage(),background:p.background,layers:structuredClone(p.layers)});await updatePortrait();toast('Portrait kept.')}catch(e){error(e)}});on('#portraitExport',async()=>{try{downloadData(await portraitImage(),'of-me-portrait.jpg')}catch(e){error(e)}});document.querySelectorAll('[data-snapshot]').forEach(b=>b.onclick=()=>{const s=p.snapshots[+b.dataset.snapshot];modal(`<h2>${esc(clock(s.date))}</h2><img class="preview" src="${safeImg(s.image)}" alt="Past portrait"><button class="btn" id="restorePortrait">Use this composition</button><button class="btn" id="downloadPortrait">Export image</button>`);on('#restorePortrait',()=>{if(confirm('Replace current composition with this snapshot?')){p.layers=structuredClone(s.layers);p.background=s.background;portraitSelected=null;closeModal();updatePortrait()}});on('#downloadPortrait',()=>downloadData(s.image,'of-me-portrait.jpg'))})}
settingsPage=function(){return baseSettings().replace('Version 0.1','Version 0.2.8 · handmade edition').replace('Make it yours','Make it mine').replace('Includes notes, collections, tags, feelings and attached media.','Includes keepsakes, Threads, tags, feelings, portraits, icons and attached media.').replace('Restore from a backup (merges by ID)','Restore from backup (replaces local archive)').replace('</section><section class="section panel stack"><h2>Quick capture','</section>'+`<section class="section panel stack"><h2>Home & texture</h2><label for="welcomeText">Welcome words</label><input id="welcomeText" autocomplete="off" value="${esc(settings.welcome??'Here I am, in all my little pieces.')}"><label>Home photo or collage</label><input id="homePhoto" type="file" accept="image/*">${safeImg(settings.homePhoto)?'<button class="ghost" id="removeHomePhoto">Remove home photo</button>':''}<div class="row"><label for="paperColor">Paper colour</label><input id="paperColor" type="color" value="${settings.background||'#f7f2e8'}"></div><label>Feather edges (keeps details sharp) <input id="feather" type="range" min="0" max="1.4" step=".1" value="${settings.feather??.45}"></label><label><input id="texture" type="checkbox" ${settings.texture!==false?'checked':''}> Paper grain</label><label><input id="onlineFonts" type="checkbox" ${settings.onlineFonts?'checked':''}> Load Cormorant Garamond and Inter online</label><p class="help">Optional Google Fonts request; otherwise use device fonts.</p><p class="help" id="appearanceStatus" role="status" aria-live="polite">Changes save automatically.</p><button class="btn" id="saveAppearance">Save appearance</button><h2>My icons</h2>${Object.entries(labels).map(([k,t])=>`<div class="icon-pick">${safeImg(settings.navIcons?.[k])?`<img class="nav-photo" src="${settings.navIcons[k]}" alt="">`:`<span>${icon(k)}</span>`}<div><label>${t}</label><input type="file" data-icon-file="${k}" accept="image/*"></div><button class="ghost" data-icon-reset="${k}">Reset</button></div>`).join('')}</section><section class="section panel stack"><h2>Media & privacy</h2><label><input type="checkbox" id="autoMetadata" ${settings.autoMetadata!==false?'checked':''}> Automatically retrieve titles and source previews</label><p class="help">Requests go directly to supported media providers; no reflection text is sent. Source thumbnails may load automatically when enabled. External players still load only when tapped.</p><button class="btn" id="manageTags">Manage tags</button><button class="btn" id="trash">Recently Deleted (${items.filter(i=>i.deletedAt).length})</button></section><section class="section panel stack"><h2>Quick capture`) };
async function saveSetting(){try{await storeSettings();applyTheme();render()}catch(e){error(e)}}
function trashDialog(){const deleted=items.filter(i=>i.deletedAt);modal(`<div class="stack"><h2>Recently Deleted</h2><p class="muted">Kept here until you permanently remove them.</p>${deleted.map(i=>`<div class="panel stack"><strong>${esc(i.title)}</strong><p class="muted">${esc(clock(i.deletedAt))}</p><div class="row"><button class="btn" data-recover="${esc(i.id)}">Restore</button><button class="danger" data-purge="${esc(i.id)}">Delete forever</button></div></div>`).join('')||'<p>Nothing here.</p>'}</div>`);document.querySelectorAll('[data-recover],[data-purge]').forEach(b=>b.onclick=async()=>{try{const i=items.find(x=>x.id===(b.dataset.recover||b.dataset.purge));if(b.dataset.purge){if(!confirm('Permanently delete this keepsake and its offline copy?'))return;await tx(['items'],'readwrite',t=>t.objectStore('items').delete(i.id))}else await tx(['items'],'readwrite',t=>t.objectStore('items').put({...i,deletedAt:null,updated:Date.now()}));await reload();render();trashDialog()}catch(e){error(e)}})}
function tagDialog(){modal(`<div class="stack"><h2>Reusable tags</h2>${settings.tags.map(t=>`<div class="row between"><strong>${esc(t)}</strong><div class="row"><button class="ghost" data-rename-tag="${esc(t)}">Rename / merge</button><button class="danger" data-delete-tag="${esc(t)}">Delete</button></div></div>`).join('')||'<p>No tags yet.</p>'}<div class="row"><input id="newGlobalTag" placeholder="New tag" style="flex:1;min-width:80px"><button class="btn" id="globalTagAdd">Add</button></div></div>`);on('#globalTagAdd',async()=>{const v=$('#newGlobalTag').value.trim();if(v&&!settings.tags.some(t=>norm(t)===norm(v))){settings.tags.push(v);settings.tags.sort();await storeSettings();render();tagDialog()}});document.querySelectorAll('[data-rename-tag],[data-delete-tag]').forEach(b=>b.onclick=async()=>{const old=b.dataset.renameTag||b.dataset.deleteTag;let v='';if(b.dataset.renameTag){v=prompt('Rename or merge into an existing tag',old);if(v===null||!v.trim())return;v=v.trim();v=settings.tags.find(t=>norm(t)===norm(v)&&t!==old)||v}else if(!confirm('Remove this tag from all keepsakes?'))return;try{settings.tags=uniq([...settings.tags.filter(t=>t!==old),...(v?[v]:[])]).sort();await tx(['items','settings'],'readwrite',t=>{const s=t.objectStore('items');items.filter(i=>i.tags?.includes(old)).forEach(i=>s.put({...i,tags:uniq([...i.tags.filter(t=>t!==old),...(v?[v]:[])]),updated:Date.now()}));t.objectStore('settings').put(settings,'main')});await reload();render();tagDialog()}catch(e){error(e)}})}
exportBackup=async function(){const b=$('#export');if(b){b.disabled=true;b.textContent='Preparing backup…'}try{const data=[];for(const i of items){const {media,...rest}=i;data.push({...rest,mediaData:media?await blobToData(media):null})}const file=new File([JSON.stringify({format:'of-me-backup',version:2,exportedAt:new Date().toISOString(),settings,items:data})],`of-me-${new Date().toISOString().replace(/[:.]/g,'-')}.json`,{type:'application/json'});const url=URL.createObjectURL(file),a=document.createElement('a');a.href=url;a.download=file.name;a.click();setTimeout(()=>URL.revokeObjectURL(url),60000);toast('Backup exported. Move it to iCloud Drive in Files.')}catch(e){error(e)}finally{if(b){b.disabled=false;b.textContent='Export complete backup'}}};
restoreBackup=async function(f){if(!f)return;try{const x=JSON.parse(await f.text());if(x.format!=='of-me-backup'||![1,2].includes(x.version)||!Array.isArray(x.items)||!Array.isArray(x.settings?.collections))throw Error('Invalid backup');const fresh=[];for(const i of x.items){if(typeof i.id!=='string'||typeof i.title!=='string'||!Number.isFinite(Number(i.created)))throw Error('Invalid keepsake');const media=i.mediaData&&/^data:(image|video|audio)\//.test(i.mediaData)?await(await fetch(i.mediaData)).blob():null;const {mediaData,...rest}=i;fresh.push({...rest,media,url:safeURL(i.url),collections:stringList(i.collections),tags:stringList(i.tags),feelings:stringList(i.feelings),thumbnail:safeImg(i.thumbnail),remoteThumb:safeURL(i.remoteThumb),reflections:Array.isArray(i.reflections)?i.reflections.filter(r=>typeof r.text==='string'):[]})}const s=x.settings;if(!s.collections.every(c=>typeof c.id==='string'&&typeof c.name==='string')||!Array.isArray(s.tags))throw Error('Invalid settings');s.background=/^#[0-9a-f]{6}$/i.test(s.background||'')?s.background:'#f7f2e8';if(s.portrait){if(!Array.isArray(s.portrait.layers)||!Array.isArray(s.portrait.snapshots)||!/^#[0-9a-f]{6}$/i.test(s.portrait.background))throw Error('Invalid portrait');for(const l of [...s.portrait.layers,...s.portrait.snapshots.flatMap(p=>p.layers||[])]){if(!Number.isFinite(l.x)||!Number.isFinite(l.y)||!Number.isFinite(l.w)||!Number.isFinite(l.r))throw Error('Invalid layer');if(l.color&&!/^#[0-9a-f]{6}$/i.test(l.color))l.color='#382c28';if(l.size&&!Number.isFinite(l.size))l.size=26}for(const p of s.portrait.snapshots)if(!/^#[0-9a-f]{6}$/i.test(p.background||''))p.background='#e8c7cf'}if(!confirm(`Replace the current archive with this backup (${fresh.length} keepsakes)? Export your current archive first if you want to keep it.`))return;await tx(['items','settings'],'readwrite',t=>{const st=t.objectStore('items');st.clear();fresh.forEach(i=>st.put(i));t.objectStore('settings').put(s,'main')});await reload();filter={q:'',collection:'',tag:'',type:'',feeling:''};render();toast('Archive restored.')}catch(e){console.error(e);toast('Could not restore this backup. Current data was not replaced.')}};
bind=function(){baseBind();if(tab==='home'){const b=$('#rediscover');if(b)b.onclick=()=>{const a=active();if(a.length)openItem(a[Math.floor(Math.random()*a.length)].id)}}if(tab==='library'){on('#allItems',()=>{setFilter('collection','');showAll=true;render()});on('#threadsBack',()=>setFilter('collection',''));on('#gridToggle',()=>{gridMode=!gridMode;render()});on('#sortMode',e=>{sortMode=e.target.value;page=0;render()},'change');on('#selectMode',()=>{selectMode=!selectMode;picked.clear();render()});on('#selectAll',()=>{picked=new Set(filtered().map(i=>i.id));render()});on('#prevPage',()=>{page--;render();window.scrollTo(0,0)});on('#nextPage',()=>{page++;render();window.scrollTo(0,0)});document.querySelectorAll('[data-pick]').forEach(b=>b.onchange=()=>{if(b.checked)picked.add(b.dataset.pick);else picked.delete(b.dataset.pick);render()});document.querySelectorAll('[data-batch]').forEach(b=>b.onclick=()=>batchDialog(b.dataset.batch));document.querySelectorAll('[data-order]').forEach(b=>b.onclick=async()=>{const c=settings.collections.find(x=>x.id===filter.collection);if(!c)return;const a=filtered().map(i=>i.id),j=a.indexOf(b.dataset.order),k=j+Number(b.dataset.dir);if(k<0||k>=a.length)return;[a[j],a[k]]=[a[k],a[j]];c.order=a;await storeSettings();render()});if(selectMode)document.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>{const id=b.dataset.open;if(picked.has(id))picked.delete(id);else picked.add(id);render()})}if(tab==='save'){on('#fetchMeta',()=>fetchMetadata(draft));on('#url',()=>{if(settings.autoMetadata!==false&&draft.url&&draft.metadataSource!==safeURL(draft.url))fetchMetadata(draft,true)},'blur');on('#thumbFile',async e=>{try{draft.thumbnail=await resizeImage(e.target.files[0]);render()}catch(e){error(e)}},'change');on('#clearThumb',()=>{draft.thumbnail='';render()});on('#title',()=>{draft.autoTitle=false},'input')}if(tab==='detail'){const i=items.find(x=>x.id===selectedId);on('#refreshSavedMeta',async()=>{try{await fetchMetadata(i);await tx(['items'],'readwrite',t=>t.objectStore('items').put({...i,updated:Date.now()}));await reload();render()}catch(e){error(e)}});on('#loadPreview',()=>{const src=safeURL(i.remoteThumb)|| (ytId(i.url)?'https://i.ytimg.com/vi/'+ytId(i.url)+'/hqdefault.jpg':'');if(src){$('#remotePreview').innerHTML=`<img class="preview" referrerpolicy="no-referrer" src="${esc(src)}" alt="Source preview">`;$('#loadPreview').disabled=true}});on('#playEmbed',()=>{const y=ytId(i.url);if(y){$('#embedArea').innerHTML=`<iframe title="YouTube player" src="https://www.youtube-nocookie.com/embed/${y}?rel=0&autoplay=0" allow="encrypted-media; picture-in-picture; fullscreen" allowfullscreen referrerpolicy="strict-origin-when-cross-origin" style="width:100%;aspect-ratio:16/9;border:0"></iframe>`;$('#playEmbed').disabled=true}})}if(tab==='mirror'){bindPortrait();on('#saveDiscovery',async()=>{const text=$('#discoveryText').value.trim();if(!text)return;settings.discoveries=[{text,date:Date.now()},...(settings.discoveries||[])];await saveSetting()});document.querySelectorAll('[data-remove-discovery]').forEach(b=>b.onclick=async()=>{if(confirm('Remove this thought?')){settings.discoveries.splice(+b.dataset.removeDiscovery,1);await saveSetting()}})}if(tab==='settings'){bindAppearance();on('#homePhoto',async e=>{try{if(e.target.files[0]){settings.homePhoto=await resizeImage(e.target.files[0]);await saveSetting()}}catch(e){error(e)}},'change');on('#removeHomePhoto',()=>{settings.homePhoto='';saveSetting()});document.querySelectorAll('[data-icon-file]').forEach(el=>el.onchange=async()=>{try{if(el.files[0]){settings.navIcons||={};settings.navIcons[el.dataset.iconFile]=await resizeImage(el.files[0],512,'image/png');await saveSetting()}}catch(e){error(e)}});document.querySelectorAll('[data-icon-reset]').forEach(b=>b.onclick=()=>{if(settings.navIcons)delete settings.navIcons[b.dataset.iconReset];saveSetting()});on('#autoMetadata',e=>{settings.autoMetadata=e.target.checked;saveSetting()},'change');on('#trash',trashDialog);on('#manageTags',tagDialog)}};
// Preserve original date and use a reversible delete. Do not add post navigation.
/* v0.2.4 enhancements */
// Keep binary assets independent of editable metadata. Existing v1 records remain readable.
const rawTx=tx;
const mediaRecords=new Map();
async function detachedMedia(blob){
  if(!(blob instanceof Blob)||!blob.size)throw Error('The attachment is empty or unavailable. Keep the original and attach it again.');
  const bytes=await blob.arrayBuffer();
  if(bytes.byteLength!==blob.size)throw Error('The attachment could not be read completely. Nothing was changed.');
  return new Blob([bytes],{type:blob.type||'application/octet-stream'});
}
